import json

# Read the JSON data
with open('/app/resources/treasury_bulletin_1941_05.json', 'r') as f:
    data = json.load(f)

# Find items related to National Defense Series
# Looking at the structure
def find_defense_series(obj, path=""):
    results = []
    if isinstance(obj, dict):
        for key, value in obj.items():
            if isinstance(value, str) and 'Defense' in value:
                results.append((path + "." + key if path else key, value))
            results.extend(find_defense_series(value, path + "." + key if path else key))
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            results.extend(find_defense_series(item, f"{path}[{i}]"))
    return results

results = find_defense_series(data)
for path, value in results:
    print(f"{path}: {value[:200] if len(str(value)) > 200 else value}")
